    if(parentPanelInfo) {
        var parentId = parentPanelInfo.parent;
        _updateMobileScroll(parentId, parentPanelInfo.stateId, true);
        if(_updateFitPanel(parentId, parentPanelInfo.state)) _fitParentPanel(parentId);
